 jk:{
  jk:{name:'Jungkook',initial:'I could listen to you sing forever. I almost forgot there were other people in the room.',options:[['“Then ask me for a private encore.”','I was hoping you would say that. Somewhere quiet after the bar?',3],['“You made it easy to sound good.”','No. You made it impossible for me to look anywhere else.',2],['“Careful—you are starting to sound like a fan.”','Too late. I think I have been one for a while.',1]]},
  san:{name:'San',initial:'We would have had much better chemistry dancing. You chose the safe option.',options:[['“Jealous, San?”','Very. Let me fix it on the dance floor later.',3],['“Think you could handle me?”','I was planning to ask you the same thing.',2],['“Jungkook earned that duet.”','Maybe. But I am claiming your first dance at the bar.',1]]},
  mingyu:{name:'Mingyu',initial:'A 98? You would have scored 100 with me. Although I would have carried the vocals.',options:[['“You think I suck at singing?”','I think provoking you is the fastest way to earn a private rematch.',3],['“Prove it, boss.”','After one drink. Loser buys breakfast.',2],['“Someone sounds competitive.”','Only when the prize is worth winning.',1]]}
 },
 san:{
  jk:{name:'Jungkook',initial:'That spin was dramatic. My moves are better—and I would not have stepped on your shoe.',options:[['“Are you challenging San?”','I am asking you to save one song for me.',3],['“Show me later, then.”','Gladly. Somewhere with less of an audience.',2],['“You were watching very closely.”','I tried not to. That did not work.',1]]},
  san:{name:'San',initial:'I can still feel you landing in my arms. Tell me you did not choose me only for the dancing.',options:[['“Maybe I liked where I landed.”','Then next time I will hold you there longer.',3],['“The chemistry helped.”','Good. I was worried I imagined the way you looked at me.',2],['“Your dancing was acceptable.”','Acceptable? I demand a private rematch.',1]]},
  mingyu:{name:'Mingyu',initial:'I have never seen you dance like that. It was impressive. It still could have been better.',options:[['“Better with you, obviously?”','You said it, not me. But yes.',3],['“Is that your version of jealousy?”','My version is inviting you for a rematch and winning.',2],['“You almost sound impressed.”','Do not make me repeat myself. I was very impressed.',1]]}
 },
 mingyu:{
  jk:{name:'Jungkook',initial:'You sounded good—even with Mingyu stealing the microphone and half your lines.',options:[['“Would you have treated me better?”','I would have given you every chorus and kept the harmonies close.',3],['“Were you jealous?”','Of the microphone, his hands at your waist, and approximately everything else.',2],['“You could have volunteered faster.”','I will not make that mistake twice.',1]]},
  san:{name:'San',initial:'You spent the whole song arguing with him. Entertaining—but dancing with me would have been hotter.',options:[['“There is still time to prove that.”','Meet me on the dance floor after our first drink.',3],['“You watched the whole performance?”','Every second. Especially the lift.',2],['“Maybe I enjoy arguing.”','Then choose me next. I can flirt and argue at the same time.',1]]},
  mingyu:{name:'Mingyu',initial:'You did not ruin my chances. We were the best pair in the room. Do not let that go to your head.',options:[['“Your hands on my waist helped.”','I noticed you did not ask me to move them.',3],['“We make a good team.”','At karaoke, at work… and perhaps somewhere less public.',2],['“I carried you, actually.”','Bold claim. We need a private rematch immediately.',1]]}
 }
