const photoFolders={'Jungkook':'jungkook','San':'san','Mingyu':'mingyu','Jennie':'jennie','Rosé':'rose','Jihyo':'jihyo','Bang Chan':'bang-chan','Joshua':'joshua','Sana':'sana','V':'v','Felix':'felix','Yunjin':'yunjin','Kazuha':'kazuha','Hanni':'hanni'};
// Storage access throws outright when site data is blocked, so every read and
// write goes through these. Reads degrade to null; writes are dropped.
const lsGet=k=>{try{return localStorage.getItem(k)}catch{return null}};
const lsSet=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};
const lsRemove=k=>{try{localStorage.removeItem(k)}catch{}};
const ssGet=k=>{try{return sessionStorage.getItem(k)}catch{return null}};
const ssSet=(k,v)=>{try{sessionStorage.setItem(k,v)}catch{}};
const photos=Object.fromEntries(Object.entries(photoFolders).map(([name,folder])=>{const options=characterImages[folder]||[];if(!options.length)return[name,null];const preferred=lsGet(`starlit-main-photo-${folder}`);if(options.includes(preferred))return[name,preferred];const libraryVersion=options.join('|'),key=`starlit-photo-${folder}-${libraryVersion}`;let selected=ssGet(key);if(!options.includes(selected)){selected=options[Math.floor(Math.random()*options.length)];ssSet(key,selected)}return[name,selected]}));
const bookCount=stories.length;
const roleCount=new Set(stories.flatMap(s=>s.cast.map(c=>c[0]))).size;
const endingCount=stories.reduce((n,s)=>{const m=s.length.match(/(\d+)[^0-9]*endings?/);return n+(m?+m[1]:0)},0);
const groupColors={BTS:'#9d80ff',ATEEZ:'#e06755',TWICE:'#fa8eb7',BLACKPINK:'#ed94b8','Stray Kids':'#e14d55',SEVENTEEN:'#8ab7dc',NewJeans:'#6bbdd0','LE SSERAFIM':'#8e91a8'};
let state={view:'home',story:null,node:null,stats:{},history:[],presenting:votingEnabled()};
const app=document.querySelector('#app');
const icon=(name)=>({spark:'✦',play:'▶',back:'←',plus:'＋',book:'▱',heart:'♥',lock:'◇'}[name]||'✦');
function nav(){return `<header class="topbar"><button class="brand" data-go="home"><span>${icon('spark')}</span> STARLIT <i>choices</i></button><nav><button data-go="library">Library</button><button data-go="cast">Cast index</button><button data-create>${icon('plus')} Create a book</button></nav></header>`}
function shell(content){app.innerHTML=`${nav()}<main>${content}</main><footer><span>STARLIT CHOICES · FAN-MADE FICTION</span><span>Made for K-pop presentation night ✦</span></footer>`;bind();}
function home(){state.view='home';shell(`<section class="hero"><div class="hero-copy"><p class="eyebrow">YOUR NIGHT. YOUR CHOICE. YOUR K-DRAMA.</p><h1>Some stories<br>are meant to be <em>chosen.</em></h1><p class="lede">Step into original K-pop–inspired romances where every glance is suspicious, every choice has consequences, and you are always the lead.</p><div class="hero-actions"><button class="primary" data-play="afterglow">${icon('play')} Start the featured story</button><button class="text-btn" data-go="library">Browse all stories <span>→</span></button></div><div class="statline"><span><b>${bookCount}</b> playable book${bookCount===1?'':'s'}</span><span><b>${endingCount}</b> possible endings</span><span><b>${roleCount}</b> idol-inspired roles</span></div></div><div class="cover-stack" aria-label="Featured story covers"><article class="cover rear c3"><span>NEW</span><h3>Second Take,<br>First Love</h3><small>A TIME-LOOP ROM-COM</small></article><article class="cover rear c2"><span>02</span><h3>The Summer<br>Between Us</h3><small>A BEACH REUNION</small></article><article class="cover featured"><div class="cover-top"><span>01</span><span>FEATURED</span></div><div class="moon">☾</div><p>A STARLIT ORIGINAL</p><h2>AFTERGLOW<br><i>PROTOCOL</i></h2><small>WHAT IF YOUR HEART<br>WAS THE FINAL CLUE?</small><div class="faces"><b>JK</b><b>YOU</b><b>SAN</b></div></article></div></section><section class="marquee"><div>YOUR CHOICES MATTER ✦ ROMANCE ✦ SECRETS ✦ SECOND CHANCES ✦ YOUR CHOICES MATTER ✦</div></section>${continueCard()}<section class="shelf"><div><p class="eyebrow dark">NOW PLAYING</p><h2>Pick your next obsession</h2></div><button class="text-btn ink" data-go="library">See the full library →</button>${storyCards()}</section>`)}
function storyCards(){return `<div class="story-grid">${stories.map((s,i)=>`<article class="story-card" style="--accent:${s.accent}"><button class="mini-cover mc${i+1}" data-play="${s.id}"><span>${s.no}</span><strong>${s.title}</strong><i>${s.genre}</i><b>${icon('play')}</b></button><div class="card-copy"><small>${s.genre}</small><h3>${s.title}</h3><p>${s.hook}</p><div>${s.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><button data-detail="${s.id}">Meet the cast →</button></div></article>`).join('')}</div>`}
function library(){state.view='library';shell(`<section class="page-head"><p class="eyebrow dark">THE LIBRARY</p><h1>Three worlds.<br><em>Sixteen ways out.</em></h1><p>Original, fan-made fiction built around public performance personas and creative traits. You are the heroine in every story.</p></section>${continueCard()}<section class="library-wrap">${storyCards()}</section>`)}
function detail(id){const s=stories.find(x=>x.id===id);state.view='detail';state.story=s;shell(`<section class="detail-hero" style="--accent:${s.accent}"><button class="back" data-go="library">${icon('back')} All stories</button><div class="detail-title"><div><p class="eyebrow">${s.no} · ${s.genre}</p><h1>${s.title}</h1><p>${s.hook}</p><button class="primary" data-play="${s.id}">${icon('play')} Play chapter one</button></div><div class="big-glyph">${s.id==='afterglow'?'☾':s.id==='velvet'?'◐':'↻'}</div></div></section><section class="cast-section"><div class="section-title"><div><p class="eyebrow dark">CASTING BOARD</p><h2>Meet your ensemble</h2></div><p>${s.length}</p></div><div class="cast-grid">${s.cast.map((c,i)=>castCard(c,i)).join('')}</div><aside class="fiction-note"><b>Creative note</b><p>Roles are fictional and inspired by each artist’s public interviews, performance identity, and music—not claims about their private lives.</p></aside></section>`)}
function castCard(c,i,editable=false){const folder=photoFolders[c[0]],options=characterImages[folder]||[],preferred=lsGet(`starlit-main-photo-${folder}`)||'';return `<article class="cast-card"><div class="portrait" style="--h:${(i*53+245)%360};--group:${groupColors[c[1]]}">${photos[c[0]]?`<img src="${photos[c[0]]}" alt="${c[0]}" loading="lazy" onerror="this.remove()">`:''}<span>${c[0].split(' ').map(x=>x[0]).join('').slice(0,2)}</span><i>${c[1]}</i></div><small>${c[2]}</small><h3>${c[0]}</h3>${editable&&folder?`<label class="portrait-picker">Main portrait<select data-photo-select="${c[0]}" data-photo-folder="${folder}"><option value="">Random each session</option>${options.map(url=>`<option value="${url}" ${preferred===url?'selected':''}>${decodeURIComponent(url.split('/').pop())}</option>`).join('')}</select></label>`:''}<p>${c[3]}</p></article>`}
function castIndex(){const seen=new Set(),all=stories.flatMap(s=>s.cast.map(c=>({...{name:c[0],group:c[1],role:c[2],trait:c[3]},story:s.title}))).filter(c=>!seen.has(c.name)&&seen.add(c.name));state.view='cast';shell(`<section class="page-head"><p class="eyebrow dark">ENSEMBLE INDEX</p><h1>Meet the <em>scene stealers.</em></h1><p>Choose each character’s main portrait below. Your selection is saved and used across books, dialogue, calls, and endings.</p></section><section class="cast-section"><div class="cast-grid">${all.map((c,i)=>castCard([c.name,c.group,c.role,c.trait],i,true)).join('')}</div></section>`)}
function storyEditsKey(s){return `starlit-edits-${s.id}${s.revision?`-v${s.revision}`:''}`}
function getNode(s,id){const raw=s.nodes[id];const base=s.id==='velvet'&&raw?book2Scene(raw,state):raw;const edits=JSON.parse(lsGet(storyEditsKey(s))||'{}');return edits[id]?{...base,...edits[id],choices:edits[id].choices||base.choices}:base}
// Save & resume: one in-progress run per book, kept in this browser. Saves are
// written on every scene render, so they always capture a scene's entry state
// (before any in-scene minigame interaction) and never double-count stats.
const PROGRESS_KEY='starlit-progress';
function allProgress(){try{const raw=JSON.parse(lsGet(PROGRESS_KEY)||'{}');return raw&&typeof raw==='object'?raw:{}}catch{return{}}}
function persistProgress(all){lsSet(PROGRESS_KEY,JSON.stringify(all))}
function saveProgress(){
 if(!state.story||typeof state.node!=='string'||state.node.endsWith('end'))return;
 const all=allProgress();
 all[state.story.id]={revision:state.story.revision,kitchenPair:state.kitchenPair,partyVisited:state.partyVisited,node:state.node,stats:state.stats,history:state.history,lastChoice:state.lastChoice,finalMan:state.finalMan,activeLove:state.activeLove,karaokePartner:state.karaokePartner,showLove:!!state.showLove,savedAt:Date.now()};
 persistProgress(all);
}
function clearProgress(id){const all=allProgress();if(all[id]){delete all[id];persistProgress(all)}}
// Returns null for anything we cannot safely resume into—a missing book, a scene
// id that no longer exists (story data changed since the save), or a finished run.
function loadProgress(id){
 const save=allProgress()[id],s=stories.find(x=>x.id===id);
 if(!s||!save||(s.revision&&save.revision!==s.revision)||typeof save.node!=='string'||save.node.endsWith('end')||!getNode(s,save.node))return null;
 return {node:save.node,
  kitchenPair:Array.isArray(save.kitchenPair)?save.kitchenPair:[],
  partyVisited:Array.isArray(save.partyVisited)?save.partyVisited:[],
  stats:save.stats&&typeof save.stats==='object'?save.stats:{},
  history:Array.isArray(save.history)?save.history:[],
  lastChoice:typeof save.lastChoice==='string'?save.lastChoice:null,
  finalMan:save.finalMan||null,
  activeLove:Array.isArray(save.activeLove)?save.activeLove:null,
  karaokePartner:save.karaokePartner||null,
  showLove:!!save.showLove,
  savedAt:Number(save.savedAt)||0};
}
function resume(id){
 const s=stories.find(x=>x.id===id),save=loadProgress(id);
 if(!s||!save)return play(id);
 // phoneDone resets: the scene re-renders fresh, so its minigame replays from the top.
 state={view:'play',story:s,kitchenPair:save.kitchenPair,partyVisited:save.partyVisited,presenting:votingEnabled(),node:save.node,stats:save.stats,history:save.history,lastChoice:save.lastChoice,admin:false,phoneDone:{},showLove:save.showLove,finalMan:save.finalMan,activeLove:save.activeLove,karaokePartner:save.karaokePartner};
 play(id,save.node,true);
}
function savedRuns(){return stories.map(s=>({s,save:loadProgress(s.id)})).filter(x=>x.save).sort((a,b)=>b.save.savedAt-a.save.savedAt)}
function continueCard(){
 const runs=savedRuns();
 if(!runs.length)return '';
 return `<section class="resume-strip"><div class="resume-head"><p class="eyebrow dark">PICK UP WHERE YOU LEFT OFF</p><h2>Continue reading</h2></div><div class="resume-grid">${runs.map(({s,save})=>{
  const n=getNode(s,save.node),pct=Math.min(96,12+(save.history.length/Object.keys(s.nodes).length)*88);
  return `<article class="resume-card" style="--accent:${s.accent}"><div><small>${s.genre}</small><h3>${s.title}</h3><p class="resume-where">${n.chapter||'In progress'}<span>${n.place}</span></p><div class="resume-bar"><i style="width:${pct}%"></i></div><small class="resume-meta">${save.history.length} choice${save.history.length===1?'':'s'} made</small></div><div class="resume-actions"><button class="primary" data-resume="${s.id}">${icon('play')} Continue</button><button class="text-btn ink" data-restart-story="${s.id}">Start over</button></div></article>`}).join('')}</div></section>`;
}
function play(id,nodeId,skipIntro=false){
 const s=stories.find(x=>x.id===id);
 if(!nodeId){state={view:'play',story:s,kitchenPair:[],partyVisited:[],node:s.start,stats:{},history:[],lastChoice:null,admin:false,phoneDone:{},showLove:false,finalMan:null,activeLove:null,karaokePartner:null,presenting:votingEnabled()};if(!skipIntro)return storyIntro(s)}else state.node=nodeId;
 const n=getNode(s,state.node);if(!n||state.node.endsWith('end'))return ending();
 const pct=Math.min(96,12+(state.history.length/Object.keys(s.nodes).length)*88),photo=photos[n.who],isTriple=n.type==='triple-phone',isDual=n.type==='dual-call',isSpecial=isTriple||isDual;
 app.innerHTML=`<div class="reader ${state.admin?'admin-active':''}" style="--accent:${s.accent}"><header><button data-exit>${icon('back')} Library</button><div><small>${n.chapter||s.title}</small><span><i style="width:${pct}%"></i></span></div><div class="reader-tools"><button data-present class="${state.presenting?'presenting':''}" title="${state.presenting?'Audience voting is on':'Audience voting is off'}">${state.presenting?'◉ Live vote':'◎ Solo'}</button><button data-admin>${state.admin?'✓ Editing':'✎ Admin'}</button><button data-restart>↻</button></div></header>${['afterglow','velvet','second'].includes(s.id)?loveDock():''}${state.lastChoice?`<div class="choice-memory"><span>YOUR LAST CHOICE</span><b>${state.lastChoice}</b><button aria-label="Dismiss">×</button></div>`:''}<section class="scene-set"><p>${n.chapter||'NEXT SCENE'}</p><h2>${n.place}</h2><div></div><span>${n.transition||''}</span></section><div class="scene-bg bg-${state.node}"><div class="orb orb1"></div><div class="orb orb2"></div><div class="character-silhouette ${photo?'has-photo':''}">${photo?`<img src="${photo}" alt="${n.who}" onerror="this.remove();this.parentElement.classList.remove('has-photo')">`:''}<span>${n.who==='You'?'YOU':n.who.split(' ').map(x=>x[0]).join('').slice(0,2)}</span></div></div><section class="dialogue ${isSpecial?'dialogue-wide':''}"><div class="speaker-row">${photo?`<img src="${photo}" alt="" onerror="this.remove()">`:''}<div><small>${n.type==='interlude'?'STORY':'SPEAKING'}</small><strong>${n.who}</strong></div></div><p class="scene-context">${n.context||''}</p>${isTriple?triplePhoneScene(n):isDual?dualCallScene():n.type==='phone'?phoneScene(n):n.type==='interlude'?`<p class="interlude-copy">${n.text}</p>`:`<p class="spoken">“${n.text}”</p>`}${isSpecial?'':`<div class="decision-label"><span>${n.type==='interlude'?'CONTINUE':'WHAT DO YOU DO?'}</span><i></i></div>${state.presenting&&visibleChoices(n).length>1?votePanel(visibleChoices(n),readerRoundId(),s.id):`<div class="choices">${visibleChoices(n).map(([c,i])=>`<button data-choice="${i}"><b>${String.fromCharCode(65+i)}</b><span>${c[0]}</span><i>→</i><small>${c[3]||''}</small></button>`).join('')}</div>`}`}</section>${state.admin?adminPanel(n):''}</div>`;bindReader();saveProgress()
}
function readerRoundId(){return `${state.story.id}-${state.node}${state.story.id==='velvet'&&state.node==='f4'?`-${(state.partyVisited||[]).join('-')||'start'}`:''}`}
function visibleChoices(n){if(state.story.id==='velvet')return book2Choices(n,state);return (n.choices||[]).map((c,i)=>[c,i]).filter(([c])=>!n.activeOnly||state.activeLove?.includes(c[4]))}
function loveConfig(){return state.story.id==='velvet'?[['jihyo','Jihyo'],['chan','Chan'],['josh','Joshua']]:state.story.id==='second'?[['v','V'],['felix','Felix']]:[['jk','Jungkook'],['san','San'],['mingyu','Mingyu']]}
function loveDock(){return `<div class="love-wrap ${state.showLove?'open':''}"><button class="love-toggle" data-love-toggle aria-expanded="${state.showLove}" title="${state.showLove?'Hide':'Show'} love meters"><span>◉</span>${state.showLove?'Hide chemistry':'Reveal chemistry'}</button><div class="love-dock">${loveConfig().map(([key,name])=>`<div data-meter="${key}" class="${state.activeLove&&!state.activeLove.includes(key)?'rejected':''}"><span>${name}</span><i><b style="width:${Math.min(100,(state.stats[key]||0)*7)}%"></b></i><strong>${state.activeLove&&!state.activeLove.includes(key)?'route closed':`${state.stats[key]||0} ♥`}</strong></div>`).join('')}</div></div>`}
function storyIntro(s){const save=loadProgress(s.id);app.innerHTML=`<div class="story-intro" style="--accent:${s.accent}"><div class="intro-blur"></div><button class="intro-exit" data-exit>${icon('back')} Library</button><div class="intro-card"><p>${s.setup.kicker}</p><h1>${s.setup.title}</h1><div class="intro-rule"></div><p class="intro-body">${s.setup.body}</p>${s.setup.roles?`<dl class="intro-roles">${s.setup.roles.map(([name,role])=>`<div><dt>${name}</dt><dd>${role}</dd></div>`).join('')}</dl>`:''}<div class="intro-stakes"><b>YOUR OBJECTIVE</b><span>${s.setup.stakes}</span></div><small>${s.setup.warning}</small><button class="primary" data-begin>${save?'Start from the beginning':'Begin chapter one →'}</button>${save?`<button class="intro-resume" data-intro-resume>${icon('play')} Continue — ${getNode(s,save.node).chapter||'in progress'}</button>`:''}</div></div>`;document.querySelector('[data-exit]').onclick=library;document.querySelector('[data-begin]').onclick=()=>{clearProgress(s.id);play(s.id,s.start,true)};document.querySelector('[data-intro-resume]')?.addEventListener('click',()=>resume(s.id))}
function phoneScene(n){return `<div class="phone"><div class="phone-top"><span>9:41</span><b>${n.who}</b><span>•••</span></div><div class="messages">${n.messages.map((m,i)=>`<div class="bubble ${m[0]==='you'?'mine':''}" style="--delay:${i*100}ms"><small>${m[0]}</small>${m[1]}</div>`).join('')}</div></div>`}
function dualCallScene(){const names={jihyo:'Jihyo',chan:'Bang Chan',josh:'Joshua'};return `<div class="dual-calls">${(state.activeLove||[]).map(key=>`<article class="ringing-phone" data-ringing="${key}"><div class="caller-photo"><img src="${photos[names[key]]||''}" alt="${names[key]}" onerror="this.remove()"><span>incoming call…</span></div><h3>${names[key]}</h3><p>is calling to check on you</p><button data-answer-call="${key}">Accept call</button></article>`).join('')}</div><button class="decline-calls" data-decline-calls>Decline both calls—I can handle this</button>`}
function answerCall(key){const el=document.querySelector(`[data-ringing="${key}"]`);document.querySelectorAll('[data-answer-call], [data-decline-calls]').forEach(b=>b.disabled=true);el?.classList.add('accepted');state.stats[key]=(state.stats[key]||0)+2;state.lastChoice=`You answered ${key==='jihyo'?'Jihyo':key==='chan'?'Bang Chan':'Joshua'}’s call.`;setTimeout(()=>{state.node=`call_${key}`;play(state.story.id,state.node,true)},state.presenting?3000:650)}
function declineCalls(){document.querySelectorAll('[data-answer-call], [data-decline-calls]').forEach(b=>b.disabled=true);state.lastChoice='You declined both calls and handled the situation yourself.';setTimeout(()=>{state.node='no_call';play(state.story.id,state.node,true)},state.presenting?3000:500)}
function currentPhoneChats(n){return n.phoneChatsByPartner?.[state.karaokePartner]||n.phoneChats}
function triplePhoneScene(n){const chats=currentPhoneChats(n);return `<div class="route-recap">After your duet with <b>${({jk:'Jungkook',san:'San',mingyu:'Mingyu'})[state.karaokePartner]||'your karaoke partner'}</b>…</div><div class="triple-phones">${Object.entries(chats).map(([key,chat])=>`<article class="mini-phone" data-chat="${key}"><div class="mini-phone-top"><img src="${photos[chat.name]||''}" alt="" onerror="this.remove()"><b>${chat.name}</b><span>online</span></div><div class="mini-thread"><div class="mini-bubble">${chat.initial}</div><div class="phone-result" data-result="${key}"></div></div><div class="text-replies">${chat.options.map((o,i)=>`<button data-text-man="${key}" data-text-option="${i}">${o[0]}<small>+${o[2]} ♥</small></button>`).join('')}</div></article>`).join('')}</div><button class="primary phone-continue" data-phone-continue disabled>Answer all three conversations</button>`}
function answerText(man,index){if(state.phoneDone[man])return;const n=getNode(state.story,state.node),option=currentPhoneChats(n)[man].options[index],phone=document.querySelector(`[data-chat="${man}"]`),result=phone.querySelector(`[data-result="${man}"]`);state.phoneDone[man]=true;state.stats[man]=(state.stats[man]||0)+option[2];phone.querySelectorAll('button').forEach(b=>b.disabled=true);result.innerHTML=`<div class="mini-bubble mine">${option[0]}</div><div class="typing">typing…</div>`;setTimeout(()=>{result.querySelector('.typing')?.remove();result.insertAdjacentHTML('beforeend',`<div class="mini-bubble response">${option[1]}</div>`);phone.classList.add('answered');updateLoveMeters();if(Object.keys(state.phoneDone).length===3){const go=document.querySelector('[data-phone-continue]');go.disabled=false;go.textContent='Continue to the bar →'}},500)}
function updateLoveMeters(){for(const [key] of loveConfig()){const el=document.querySelector(`[data-meter="${key}"]`);if(el&&!el.classList.contains('rejected')){el.querySelector('b').style.width=`${Math.min(100,(state.stats[key]||0)*7)}%`;el.querySelector('strong').textContent=`${state.stats[key]||0} ♥`}}}
function advancePhone(){const n=getNode(state.story,state.node);state.lastChoice='You answered all three men—and made each one want your attention more.';state.history.push({node:state.node,choice:'Three private replies'});state.phoneDone={};state.node=n.next;play(state.story.id,state.node,true)}
function choose(i){const n=getNode(state.story,state.node),c=n.choices[i];if(!visibleChoices(n).some(([,index])=>index===i))return;const btn=document.querySelector(`[data-choice="${i}"]`);document.querySelectorAll('[data-choice]').forEach(x=>x.disabled=true);btn?.classList.add('chosen');state.lastChoice=c[0];Object.entries(c[2]||{}).forEach(([k,v])=>state.stats[k]=(state.stats[k]||0)+v);state.history.push({node:state.node,choice:c[0]});let next=c[1],consequence=c[3]||'The story shifts around your decision.';if(state.story.id==='velvet')next=advanceBook2(n,c,state);if(n.setActivePair){state.activeLove=c[5];const all=['jihyo','chan','josh'],closed=all.find(x=>!state.activeLove.includes(x)),names={jihyo:'Jihyo',chan:'Bang Chan',josh:'Joshua'};consequence=`${names[closed]} takes the work call and steps out. Their romance route is now closed; your chemistry with the other two rises.`}if(state.node==='d2')state.karaokePartner=next==='k_jk'?'jk':next==='k_san'?'san':'mingyu';if(n.routeByTopActive){const top=[...(state.activeLove||[])].sort((a,b)=>(state.stats[b]||0)-(state.stats[a]||0))[0];state.finalMan=top;next=`confess_${top}`;const names={jihyo:'Jihyo',chan:'Bang Chan',josh:'Joshua'};consequence=`The others drift away along the shoreline. ${names[top]}, your strongest connection, stays beside the fire.`}if(n.routeByTopWedding){const top=(state.stats.v||0)>=(state.stats.felix||0)?'v':'felix';if(state.node==='w10'){state.finalMan=c[0].includes('yourself')?null:c[0].includes('V.')?'v':top}else state.finalMan=top;const name=state.finalMan==='v'?'V':'Felix';if(state.finalMan)consequence=`Every choice has been pulling you closer to ${name}. The next scene follows that connection.`}if(n.routeByLove&&c[4]){if(c[4]==='all'){state.finalMan=null}else{const top=['jk','san','mingyu'].sort((a,b)=>(state.stats[b]||0)-(state.stats[a]||0))[0];state.finalMan=(state.stats[top]||0)>(state.stats[c[4]]||0)?top:c[4];if(state.finalMan!==c[4]){next=`steal_${state.finalMan}`;consequence='Your chosen ride is interrupted before anyone can leave. Someone else is about to step forward.'}}}setTimeout(()=>{document.body.insertAdjacentHTML('beforeend',`<div class="transition-card"><small>${state.presenting?'THE ROOM CHOSE':'YOU CHOSE'}</small><strong>${c[0]}</strong><p>${consequence}</p></div>`);setTimeout(()=>{const card=document.querySelector('.transition-card');card?.classList.add('leave');state.node=next;setTimeout(()=>{card?.remove();play(state.story.id,state.node,true)},350)},transitionHold())},350)}
// The consequence card is a paragraph a whole room reads off a projector,
// so presentation mode holds it far longer than a solo reader needs.
function transitionHold(){return state.presenting?5000:950}
function adminPanel(n){return `<aside class="admin-panel"><div><p>STORY ADMIN</p><h3>Edit this scene</h3><small>Changes save only in this browser. Refresh-safe.</small></div><label>Location<input data-edit="place" value="${escapeHtml(n.place)}"></label><label>Arrival / transition<textarea data-edit="transition">${escapeHtml(n.transition||'')}</textarea></label><label>Scene context<textarea data-edit="context" rows="4">${escapeHtml(n.context||'')}</textarea></label><label>Dialogue<textarea data-edit="text" rows="3">${escapeHtml(n.text||'')}</textarea></label><div class="admin-options">${(n.choices||[]).map((c,i)=>`<label>Option ${String.fromCharCode(65+i)}<input data-option="${i}" value="${escapeHtml(c[0])}"></label>`).join('')}</div><button class="primary" data-save-scene>Save scene</button><button class="ghost ink" data-reset-scene>Restore original</button></aside>`}
function escapeHtml(v=''){return String(v).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
function bindReader(){bind();document.querySelector('[data-admin]')?.addEventListener('click',()=>{state.admin=!state.admin;play(state.story.id,state.node,true)});document.querySelector('[data-present]')?.addEventListener('click',()=>{const on=!state.presenting;setVotingEnabled(on);state.presenting=on;stopRound();play(state.story.id,state.node,true)});if(document.querySelector('[data-vote-panel]')){const n=getNode(state.story,state.node);runRound(readerRoundId(),visibleChoices(n),i=>choose(i),{room:state.story.id,chapter:n.chapter||''})}document.querySelector('[data-love-toggle]')?.addEventListener('click',()=>{state.showLove=!state.showLove;document.querySelector('.love-wrap')?.classList.toggle('open',state.showLove);const b=document.querySelector('[data-love-toggle]');b.setAttribute('aria-expanded',String(state.showLove));b.lastChild.textContent=state.showLove?'Hide chemistry':'Reveal chemistry'});document.querySelector('.choice-memory button')?.addEventListener('click',e=>{e.currentTarget.parentElement.remove();state.lastChoice=null});document.querySelectorAll('[data-text-man]').forEach(b=>b.onclick=()=>answerText(b.dataset.textMan,Number(b.dataset.textOption)));document.querySelectorAll('[data-answer-call]').forEach(b=>b.onclick=()=>answerCall(b.dataset.answerCall));document.querySelector('[data-decline-calls]')?.addEventListener('click',declineCalls);document.querySelector('[data-phone-continue]')?.addEventListener('click',advancePhone);document.querySelector('[data-save-scene]')?.addEventListener('click',saveScene);document.querySelector('[data-reset-scene]')?.addEventListener('click',()=>{const all=JSON.parse(lsGet(storyEditsKey(state.story))||'{}');delete all[state.node];lsSet(storyEditsKey(state.story),JSON.stringify(all));play(state.story.id,state.node,true)})}
function saveScene(){const n=getNode(state.story,state.node),edit={};document.querySelectorAll('[data-edit]').forEach(x=>edit[x.dataset.edit]=x.value);if(n.choices)edit.choices=n.choices.map((c,i)=>[document.querySelector(`[data-option="${i}"]`).value,c[1],c[2],c[3],c[4],c[5]]);const all=JSON.parse(lsGet(storyEditsKey(state.story))||'{}');all[state.node]=edit;lsSet(storyEditsKey(state.story),JSON.stringify(all));state.admin=false;play(state.story.id,state.node,true)}
function ending(){const v=state.stats;let title,sub,endingMan=null;
 if(state.story.id==='afterglow'){const key=state.finalMan||((v.jk||0)>=(v.san||0)&&(v.jk||0)>=(v.mingyu||0)?'jk':(v.san||0)>=(v.mingyu||0)?'san':'mingyu'),names={jk:'Jungkook',san:'San',mingyu:'Mingyu'},man=names[key];endingMan=v.chaos?null:man;if(v.stay){title=`Morning After with ${man}`;sub=`You stay. The city fades behind the curtains, the office disappears, and the night becomes something private and unforgettable. On Monday, ${man} leaves your favorite coffee on your desk with a note: “Dinner tonight—no coworkers, no competition.”`}else if(v.slow){title=`The Real First Date`;sub=`You kiss ${man} at the elevator and go home smiling. He texts before you reach the street: “Tomorrow. Seven. Let me do this properly.” The anticipation is almost better than staying.`}else if(v.reject){title=`The Kiss You Left Behind`;sub=`You kiss ${man} goodnight and close the door alone. It is not rejection—it is a boundary. On Monday, the way he looks across the conference table promises the story is far from over.`}else{title='Breakfast for Four';sub='You choose friendship before possession. Breakfast is hilarious, painfully awkward, and honest. The competition is not over—but now it happens on your terms.'}}
 else if(state.story.id==='velvet'){({title,sub,endingMan}=book2Ending(state))}
 else {const man=state.finalMan==='felix'?'Felix':state.finalMan==='v'?'V':(v.v||0)>=(v.felix||0)?'V':'Felix';endingMan=v.solo?null:man;if(v.solo){title='Make Them Court You';sub='You leave the wedding with Hanni and no boyfriend. Both men receive the same message the next morning: “If you are serious, ask me on a real date.” For once, you are not waiting for anyone.'}else if(v.chooseV||state.finalMan==='v'){title='No More Pretending';sub='You tear the contract in half. V kisses you outside the chapel with no cameras and no audience. The actor who played your boyfriend finally gets to become him.'}else{title=`The Man Outside the Chapel`;sub=`You find ${man} waiting in the sunlight and ask him to stay. He does. Your ex gets a perfect wedding; you get the imperfect, heart-racing beginning you actually wanted.`}}
 app.innerHTML=`<div class="ending" style="--accent:${state.story.accent}"><div class="ending-stars">✦　·　✧　·　✦</div><p>ENDING UNLOCKED</p><h1>${title}</h1>${endingMan?`<div class="ending-couple"><img src="${photos[endingMan]}" alt="${endingMan}" onerror="this.remove()"><span>Y/N <b>♥</b> ${endingMan}</span></div>`:`<div class="end-seal">${icon('heart')}</div>`}<p class="ending-copy">${sub}</p><div class="ending-actions"><button class="primary" data-restart>↻ Try another route</button><button class="ghost" data-exit>Back to library</button></div><small>${state.history.length} choices made · Your ending has been saved</small></div>`;lsSet(`ending-${state.story.id}`,title);clearProgress(state.story.id);bind()}
function closeModal(){document.removeEventListener('keydown',modalKeydown);document.querySelector('.modal-wrap')?.remove();lastFocus?.focus?.();lastFocus=null}
function modalKeydown(e){if(e.key==='Escape'){e.preventDefault();closeModal()}}
let lastFocus=null;
function createModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" role="dialog" aria-modal="true" aria-label="Create a book"><form class="modal"><button type="button" class="close" data-close aria-label="Close">×</button><p class="eyebrow dark">STORY STUDIO</p><h2>Create your book</h2><p>Start a new story bible. It will be saved in this browser.</p><label>Book title<input name="title" required placeholder="e.g. Moonlight Contract"></label><label>Genre<select name="genre"><option>Romance</option><option>Mystery</option><option>Thriller</option><option>Rom-com</option><option>Fantasy</option></select></label><label>Elevator pitch<textarea name="pitch" required placeholder="You wake up engaged to your rival..." rows="3"></textarea></label><div class="row"><label>Main love interest<input name="lead" placeholder="Character name"></label><label>Best friend<input name="friend" placeholder="Character name"></label></div><button class="primary" type="submit">${icon('book')} Save story bible</button><button type="button" class="modal-cancel" data-close>Cancel</button></form></div>`);lastFocus=document.activeElement;const wrap=document.querySelector('.modal-wrap');document.querySelector('.modal input').focus();document.querySelector('.modal').addEventListener('submit',saveBook);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);wrap.addEventListener('click',e=>{if(e.target===wrap)closeModal()});document.addEventListener('keydown',modalKeydown)}
function saveBook(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));const saved=JSON.parse(lsGet('starlit-books')||'[]');saved.push(d);lsSet('starlit-books',JSON.stringify(saved));document.querySelector('.modal').innerHTML=`<div class="success">✦</div><h2>${d.title} is ready.</h2><p>Your ${d.genre.toLowerCase()} story bible has been saved. Next, build scenes and choices around “${d.pitch}”</p><button class="primary" type="button" data-done>Back to the library</button>`;document.querySelector('[data-done]').onclick=()=>{closeModal();library()}}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>({home,library,cast:castIndex}[b.dataset.go]||home)());document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>play(b.dataset.play));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.choice)));document.querySelectorAll('[data-photo-select]').forEach(s=>s.onchange=()=>{const name=s.dataset.photoSelect,folder=s.dataset.photoFolder,options=characterImages[folder]||[];if(s.value){lsSet(`starlit-main-photo-${folder}`,s.value);photos[name]=s.value}else{lsRemove(`starlit-main-photo-${folder}`);photos[name]=options[Math.floor(Math.random()*options.length)]||null}castIndex()});document.querySelectorAll('[data-create]').forEach(b=>b.onclick=createModal);document.querySelectorAll('[data-exit]').forEach(b=>b.onclick=library);document.querySelectorAll('[data-restart]').forEach(b=>b.onclick=()=>{clearProgress(state.story.id);play(state.story.id)});document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>resume(b.dataset.resume));document.querySelectorAll('[data-restart-story]').forEach(b=>b.onclick=()=>{clearProgress(b.dataset.restartStory);play(b.dataset.restartStory)})}
home();
